function coherenceUI(){
 const d=globalThis.SteroidGuide.diagnostic(A.answers);
 return '<section class="fit-onboard coherence-screen"><div class="fit-onboard-head"><button class="fit-back" type="button" data-action="guide-close" aria-label="Retour au questionnaire">‹</button><div class="fit-step-progress"><span class="active"></span><span class="active"></span><span class="active"></span><span class="active"></span><span class="active"></span><span class="active"></span><span class="active"></span></div><span class="fit-step-count">BILAN</span></div><div class="coherence-body"><span class="fit-kicker">ANALYSE DE TON PROGRAMME</span><h1>On ajuste avant de commencer.</h1><p class="coherence-intro">Tes réponses ne sont pas mauvaises. Certaines ne vont simplement pas bien ensemble. Voici les points à améliorer pour construire un programme cohérent.</p><div class="coherence-issues">'+d.issues.map((issue,i)=>'<article class="coherence-issue"><div class="coherence-issue-head"><span class="coherence-index">'+String(i+1).padStart(2,'0')+'</span><strong>'+esc(issue.title)+'</strong></div><p>'+esc(issue.reason)+'</p><button type="button" data-action="guide-edit" data-step="'+issue.stage+'">Modifier cette réponse <span aria-hidden="true">↗</span></button></article>').join('')+'</div>'+(d.choices.length?'<h2>Ce que je te conseille</h2><p class="coherence-subtitle">Ces propositions corrigent les incompatibilités d’entraînement détectées. Tes objectifs et tes autres réponses sont conservés.</p><div class="coherence-choices">'+d.choices.map((x,i)=>'<article class="coherence-choice"><div><span class="coherence-tag">'+(i===0?'RECOMMANDÉ':'ALTERNATIVE')+'</span><h3>'+esc(x.title)+'</h3><p>'+esc(x.why)+'</p></div><button type="button" data-action="guide-apply" data-index="'+i+'">Appliquer <span aria-hidden="true">→</span></button></article>').join('')+'</div>':'')+(d.issues.some(x=>x.code==='LIMITATIONS_REVIEW')?'<p class="coherence-health">Une douleur ou limitation ne doit jamais être effacée pour obtenir un résultat « compatible ». Garde cette information et fais vérifier les mouvements avant de commencer.</p>':'')+'</div><div class="fit-onboard-footer coherence-footer"><button type="button" class="fit-outline" data-action="guide-close">Revoir mes réponses</button></div></section>';
}
function onboardUI(){if(A.guide)return coherenceUI();const stage=onboardingStages[A.step],fields=eng().steps.flatMap(s=>s.fields).filter(f=>stage.keys.includes(f.key));return '<section class="fit-onboard"><div class="fit-onboard-head"><button type="button" class="fit-back" data-action="'+(A.step?'prev-step':'onboard-exit')+'" aria-label="Retour">‹</button><div class="fit-step-progress" aria-label="Étape '+(A.step+1)+' sur '+onboardingStages.length+'">'+onboardingStages.map((_,i)=>'<span class="'+(i<=A.step?'active':'')+'"></span>').join('')+'</div><span class="fit-step-count">'+String(A.step+1).padStart(2,'0')+'/'+String(onboardingStages.length).padStart(2,'0')+'</span></div><div class="fit-onboard-body"><div class="fit-question"><span class="fit-kicker">TON COACH TE DEMANDE</span><h1>'+esc(stage.title)+'</h1><p>'+esc(stage.subtitle)+'</p></div><div class="fit-answers">'+fields.map(f=>'<div class="profile-field"><label class="field-label">'+esc(f.label)+'</label>'+profileField(f)+'</div>').join('')+'</div><div class="fit-coach-line">'+esc(stage.quip)+'</div></div><div class="fit-onboard-footer"><button class="fit-action" data-action="next-step">'+(A.step===onboardingStages.length-1?'Créer mon programme':'Suivant')+' <span>→</span></button></div></section>'}

function accountUI(){
 if(A.mode==='reset'&&A.session)return '<div class="auth-panel"><div class="auth-headline"><span class="auth-kicker">ACCÈS SÉCURISÉ</span><h1>Un nouveau départ.</h1><p>Définis ton mot de passe pour retrouver ton espace.</p></div><form id="password-form" class="auth-form"><label class="field-label">Nouveau mot de passe</label><input name="password" type="password" minlength="8" required autocomplete="new-password"><button class="primary save" type="submit">Enregistrer mon mot de passe <span>→</span></button></form></div>';
 if(A.session)return '<div class="auth-panel"><div class="auth-headline"><span class="auth-kicker">MON ESPACE</span><h1>Heureux de te revoir.</h1><p>'+esc(A.session.user?.email||'Compte connecté')+'</p></div><button class="primary save" data-action="back-app">Reprendre mon entraînement →</button><button class="auth-text-link" data-action="edit-profile">Adapter mon programme</button><button class="auth-text-link" data-action="logout">Me déconnecter</button></div>';
 const signup=A.mode==='signup',recover=A.mode==='recover',verify=A.mode==='verify';
 const title=signup?'Créer mon compte':recover?'Récupérer mon accès':verify?'Confirme ton adresse':'Connexion';
 const intro=signup?'Enregistre ton programme et retrouve tes séances.':recover?'Nous t’enverrons un lien par email.':verify?'Vérifie ta boîte mail et les spams.':'Retrouve ton programme et tes performances.';
 const fields=verify?'':'<form id="auth-form" class="auth-form"><label class="field-label" for="auth-email">Adresse email</label><input id="auth-email" name="email" type="email" autocomplete="email" required placeholder="ton@email.fr" value="'+esc(A.email||'')+'">'+(recover?'':'<label class="field-label" for="auth-password">Mot de passe</label><input id="auth-password" name="password" type="password" autocomplete="'+(signup?'new-password':'current-password')+'" required minlength="8" placeholder="8 caractères minimum">')+'<button class="primary save" type="submit">'+(recover?'Recevoir le lien':signup?'Créer mon compte':'Me connecter')+' <span aria-hidden="true">→</span></button></form>';
 const alternative=signup?'<p class="auth-switch">Déjà un compte ? <button data-action="auth-login">Me connecter</button></p>':recover||verify?'<p class="auth-switch"><button data-action="auth-login">Retour à la connexion</button></p>':'<p class="auth-switch">Je n’ai pas de compte. <button data-action="auth-signup">Créer mon compte</button></p>';
 return '<div class="auth-panel"><div class="auth-headline"><span class="auth-kicker">STÉROÏDE · TON COACH</span><h1>'+title+'</h1><p>'+intro+'</p></div><div class="auth-glass">'+fields+(verify?'<button class="primary save" data-action="resend-confirm">Renvoyer l’email →</button>':'')+alternative+(!signup&&!recover&&!verify?'<button class="auth-forgot" data-action="auth-recover">Mot de passe oublié ?</button>':'')+'<div class="auth-or"><span>OU</span></div><button class="auth-guest" data-action="guest">Utiliser sans compte <span>↗</span></button></div></div>';
}

async function finishOnboarding(){const p=A.answers;if(Number(p.age)&&Number(p.age)<18){setNotice('STÉROÏDE est réservé aux adultes pour le moment.',true);return}
 const d=globalThis.SteroidGuide.diagnostic(p);
 if(!d.ok){A.guide=true;render();scrollToSectionTop();return}
 let program;
 try{program=eng().buildProgram(p)}catch(e){setNotice(e.message||'Impossible de générer ce programme.',true);return}S.plan=program;A.profile={answers:structuredClone(p),method:p.method};S.start=iso(monday(new Date()));S.logs=[];S.week=1;S.tab='today';S.open='auto';A.view='app';localStorage.setItem('nolsprog-onboarding-seen','1');if(!A.session)persist();else cacheAccount();render();
 if(A.session){try{await cloud('user_profiles?on_conflict=user_id',{method:'POST',prefer:'resolution=merge-duplicates',body:{user_id:A.session.user.id,answers:p,method:p.method}});await syncProgram();A.profile={answers:p,method:p.method};setNotice('Programme personnalisé créé et synchronisé ✓')}catch(e){setNotice('Programme créé localement, mais synchronisation impossible : '+e.message,true)}}
 else setNotice('Programme créé sur cet appareil ✓')
}
async function initAuth(){const hash=new URLSearchParams(location.hash.slice(1));if(hash.get('access_token')&&hash.get('refresh_token')){try{const access_token=hash.get('access_token'),refresh_token=hash.get('refresh_token');const user=await req('/auth/v1/user',{token:access_token});setSession({access_token,refresh_token,user,expires_at:Math.floor(Date.now()/1000)+Number(hash.get('expires_in')||3600)});history.replaceState(null,'',location.pathname+location.search);if(hash.get('type')==='recovery'){A.view='account';A.mode='reset';render();return}await loadCloud();return}catch(e){history.replaceState(null,'',location.pathname+location.search);setNotice('Lien expiré ou invalide : '+e.message,true)}}try{const saved=localStorage.getItem(AUTH_KEY);if(saved)A.session=JSON.parse(saved)}catch{}if(A.session){try{if(await renew()){await loadCloud();return}}catch(e){console.warn('NolsProg: chargement du compte impossible',e);try{const cached=JSON.parse(localStorage.getItem(accountCacheKey(A.session.user.id)));if(cached&&Array.isArray(cached.plan)){S.plan=cached.plan;S.start=cached.start;S.logs=cached.logs||[];S.week=currentWeek(S.start);A.view='app';setNotice('Mode hors ligne : dernières données locales du compte.',true);return}}catch{}A.view='account';render();return}}
 A.view=localStorage.getItem('nolsprog-onboarding-seen')==='1'?'app':'welcome';render()}
function welcomeUI(){return '<section class="fit-entry"><div class="fit-entry-top"><span class="fit-overline">STÉROÏDE · TRAINING CLUB</span><h1>Entraîne-toi<br><em>plus intelligent.</em></h1></div><div class="fit-logo"><img class="steroid-mark" src="./steroid-icon.svg" alt="" aria-hidden="true"><img class="fit-wordmark official-wordmark" src="./steroide-wordmark.svg" alt="STÉROÏDE"></div><div class="fit-entry-bottom"><p>Ton programme. Tes séances.<br>Ta progression, à ton rythme.</p><button class="fit-action" data-action="auth-signup">Commencer <span>→</span></button><button class="fit-outline" data-action="auth-login">Me connecter</button><button class="fit-quiet" data-action="guest">Utiliser sans compte</button></div></section>'}

function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify({version:1,plan:S.plan,start:S.start,logs:S.logs,answers:A.answers||A.profile?.answers||null}));return true}catch(e){setNotice('Stockage local indisponible : exporte tes données avant de quitter.',true);return false}}
function loadLocal(){loadWorkouts();restoreRest();try{const raw=localStorage.getItem(STORAGE_KEY);const data=raw?JSON.parse(raw):null;if(data&&Array.isArray(data.plan)&&data.plan.length===7&&Array.isArray(data.logs)&&typeof data.start==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(data.start)){S.plan=data.plan;S.start=data.start;A.answers=data.answers||null;S.logs=data.logs.filter(x=>x&&Number.isInteger(x.week_number)&&Number.isInteger(x.day_index)&&typeof x.exercise_id==='string'&&Number.isInteger(x.set_number)).slice(-20000)}else{S.plan=seed();S.start=iso(monday(new Date()));S.logs=[];persist()}}catch(e){S.plan=seed();S.start=iso(monday(new Date()));S.logs=[];setNotice('Lecture du stockage impossible. Vérifie les paramètres du navigateur.',true)}S.week=currentWeek(S.start);try{ensureWeekPlan(S.week)}catch(e){setNotice('Calendrier indisponible : '+e.message,true)}render()}
function downloadBackup(){const payload=JSON.stringify({app:'NolsProg',version:1,exported_at:new Date().toISOString(),plan:S.plan,start:S.start,logs:S.logs,answers:A.answers||A.profile?.answers||null},null,2);const blob=new Blob([payload],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='nolsprog-sauvegarde-'+iso(new Date())+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const monday=d=>{let x=new Date(d);x.setHours(12,0,0,0);x.setDate(x.getDate()-(x.getDay()+6)%7);return x};
const iso=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const currentWeek=s=>Math.max(1,Math.floor((monday(new Date())-monday(new Date(s+'T12:00:00')))/604800000)+1);
const setNotice=(msg,error=false)=>{S.notice=msg;S.error=error;render();setTimeout(()=>{if(S.notice===msg){S.notice='';render()}},6500)};
// Weekly plans are immutable snapshots persisted inside the existing plan JSON.
// This preserves exercise IDs and historical set records across navigation/reloads.
function currentPlan(){
 const weeks=S.plan?.[0]?.weeklyPlans;
 return S.week>1&&Array.isArray(weeks?.[S.week])?weeks[S.week]:S.plan;
}
function ensureWeekPlan(week){
 if(week<=1||week>52||!S.plan?.length)return;
 if(!S.plan[0].weeklyPlans)S.plan[0].weeklyPlans={};
 if(S.plan[0].weeklyPlans[week])return;
 const profile=A.profile?.answers||A.answers;
 if(!profile||!globalThis.NolsEngine?.buildProgram)return;
 const generated=eng().buildProgram(profile,week-1);
 // IDs are scoped to the week; snapshots are never regenerated once recorded.
 for(let day=0;day<generated.length;day++)for(let i=0;i<generated[day].ex.length;i++){
  generated[day].ex[i].id='w'+week+'-d'+day+'-e'+i;
 }
 S.plan[0].weeklyPlans[week]=generated;
 if(A.session){cacheAccount();syncProgram().catch(e=>setNotice('Synchronisation du calendrier en attente : '+e.message,true))}
 else persist();
}
// Compare exercise names across weekly snapshots; IDs are week-scoped.
function previousExerciseLogs(day,name,week=S.week){
 for(let w=week-1;w>=1;w--){
  const plan=w===1?S.plan:S.plan?.[0]?.weeklyPlans?.[w];
  const ex=plan?.[day]?.ex.find(x=>x.name===name);
  if(!ex)continue;
  const rows=S.logs.filter(r=>r.week_number===w&&r.day_index===day&&r.exercise_id===ex.id);
  if(rows.length)return rows;
 }
 return [];
}
function progressionHint(ex,day){
 const rows=S.logs.filter(r=>r.week_number===S.week&&r.day_index===day&&r.exercise_id===ex.id);
 const result=globalThis.SteroidProgression?.evaluate(ex,rows);
 if(!result)return '';
 const label=result.status==='verify'?'Vérifier le RIR':result.status==='reps'?'Double progression':'';
 return label?'<p class="previous"><strong>'+esc(label)+' :</strong> '+esc(result.message)+(result.status==='verify'?'<button type="button" data-action="verify-rir" data-ex="'+esc(ex.id)+'">Évaluer ma marge ↗</button>':'')+'</p>':'';
}
const logFor=(d,id,s,w=S.week)=>S.logs.find(l=>l.day_index===d&&l.exercise_id===id&&l.set_number===s+1&&l.week_number===w);
const allEx=()=>currentPlan().flatMap((p,d)=>p.ex.map(ex=>({id:d+'|'+ex.id,label:p.day+' · '+ex.name})));
const formatRest=seconds=>{const n=Math.max(0,Number(seconds)||0);if(n<=60)return n+' s';const m=Math.floor(n/60),s=n%60;return m+' min'+(s?' '+String(s).padStart(2,'0'):'')};
const selectedDate=index=>{const d=new Date(S.start+'T12:00:00');d.setDate(d.getDate()+(S.week-1)*7+index);return d};
const dateText=()=>{const d=new Date(S.start+'T12:00:00');d.setDate(d.getDate()+(S.week-1)*7);const end=new Date(d);end.setDate(d.getDate()+6);return d.toLocaleDateString('fr-FR',{day:'numeric',month:'short'})+' – '+end.toLocaleDateString('fr-FR',{day:'numeric',month:'short'})};
const buttonNav=(tab,icon,label)=>'<button class="'+(S.tab===tab?'active':'')+'" data-action="tab" data-tab="'+tab+'"><span class="tabicon">'+icon+'</span>'+label+'</button>';
function cycleReviewUI(){
 if(S.week<6||S.week%6!==0)return '';
 const completed=S.logs.filter(r=>r.completed&&r.week_number>=S.week-5&&r.week_number<=S.week).length;
 return '<section class="rest"><h3>Bilan de tes 6 semaines</h3><p>'+completed+' séries validées sur ce cycle. Fais le point sur ta progression, ta récupération et tes exercices. Aucun changement automatique : ton programme reste en place tant que tu ne le modifies pas.</p><button data-action="cycle-review">Faire mon bilan ↗</button></section>';
}
function todayUI(){const p=currentPlan()[S.day],total=p.ex.reduce((n,e)=>n+e.sets,0),done=p.ex.reduce((n,e)=>n+Array.from({length:e.sets},(_,s)=>logFor(S.day,e.id,s)?.completed?1:0).reduce((a,b)=>a+b,0),0);const days=currentPlan().map((d,i)=>{const date=selectedDate(i),today=iso(date)===iso(new Date());return '<button aria-label="'+esc(d.day+' '+date.toLocaleDateString('fr-FR',{day:'numeric',month:'long'}))+'" data-action="day" data-day="'+i+'" class="'+(i===S.day?'active':'')+(today?' is-today':'')+'"><small>'+d.day.slice(0,3).toUpperCase()+'</small><strong>'+date.getDate()+'</strong></button>'}).join('');let main='<div class="eyebrow">AU BOULOT, CHAMPION</div><h1 class="hero-title">Les excuses,<br><em>ça ne muscle pas.</em></h1><div class="week"><button data-action="week" data-step="-1">‹</button><strong>SEMAINE '+S.week+'</strong><button data-action="week" data-step="1">›</button><small>'+dateText()+'</small></div><div class="days">'+days+'</div><section class="hero"><div class="eyebrow">'+esc(p.day.toUpperCase())+' · '+(total?'ENTRAÎNEMENT':'RÉCUPÉRATION')+'</div><h2>'+esc(p.title)+'</h2><p>'+esc(p.focus)+'</p>'+(total?'<div class="track"><i style="width:'+Math.round(done/total*100)+'%"></i></div><div class="space"><small>'+done+' / '+total+' séries terminées</small><strong>'+Math.round(done/total*100)+'%</strong></div>':'')+'</section>';if(!total)return main+'<section class="rest"><div class="symbol">'+(S.day===3?'↗':'☾')+'</div><h3>'+esc(p.title)+'</h3><p>'+(S.day===3?'20–40 minutes de marche ou cardio léger et 10 minutes de mobilité.':'Récupération complète.')+'</p></section>';const workout=activeWorkout();if(workout?.status==='active')main+='<div class="workout-entry"><button class="fit-action" data-action="workout-guided">'+(workout.mode==='guided'?'Reprendre le parcours guidé':'Passer en mode guidé')+'</button><button class="fit-outline" data-action="workout-request-finish">Terminer ma séance</button></div>';else if(!workout)main+='<div class="workout-entry"><button class="fit-action" data-action="workout-guided">Commencer en mode guidé</button><button class="fit-outline" data-action="workout-classic">Commencer en liste classique</button></div>';else main+='<div class="workout-entry"><button class="fit-outline" data-action="workout-show-summary">Voir le bilan de séance</button></div>';if(S.finishPrompt&&workout?.status==='active')main+=finishPromptUI();main+=cycleReviewUI();main+='<div class="section-title"><h3>Exercices <span>'+p.ex.length+'</span></h3><button data-action="tab" data-tab="edit">Modifier ↗</button></div>';p.ex.forEach((ex,i)=>{const finished=Array.from({length:ex.sets},(_,s)=>logFor(S.day,ex.id,s)?.completed?1:0).reduce((a,b)=>a+b,0),opened=S.open===ex.id||(S.open==='auto'&&i===0);main+='<section class="exercise"><button class="ex-head" data-action="open" data-id="'+esc(ex.id)+'"><span class="num">'+String(i+1).padStart(2,'0')+'</span><span class="ex-name"><strong>'+esc(ex.name)+'</strong><small>'+ex.sets+' séries · '+esc(ex.reps)+' reps · '+(ex.targetWeight!==null&&ex.targetWeight!==undefined?ex.targetWeight+' kg cible · ':'')+formatRest(ex.rest)+' repos</small></span><span class="count">'+finished+'/'+ex.sets+'</span><span class="chevron">'+(opened?'⌄':'›')+'</span></button>';if(opened){main+='<div class="sets"><div class="set-row labels"><span>SÉRIE</span><span>KG</span><span>REPS</span><span>FAIT</span></div>';for(let s=0;s<ex.sets;s++){const r=logFor(S.day,ex.id,s),prev=previousExerciseLogs(S.day,ex.name)[s];main+='<div class="set-row"><strong class="set-index" aria-label="Série '+(s+1)+'">'+(s+1)+'</strong><input data-field="weight" data-ex="'+esc(ex.id)+'" data-set="'+s+'" type="number" inputmode="decimal" min="0" step="0.5" placeholder="'+esc(prev?.weight??ex.targetWeight??'—')+'" value="'+esc(r?.weight??'')+'"><input data-field="reps" data-ex="'+esc(ex.id)+'" data-set="'+s+'" type="number" inputmode="numeric" min="0" step="1" placeholder="'+esc(prev?.reps??'—')+'" value="'+esc(r?.reps??'')+'"><button class="check '+(r?.completed?'checked':'')+'" data-action="complete" data-ex="'+esc(ex.id)+'" data-set="'+s+'">✓</button></div>'}main+='<p class="previous">Les valeurs grisées correspondent à une séance antérieure du même exercice.</p>'+progressionHint(ex,S.day)+'</div>'}main+='</section>'});return main}
function chartData(){const ex=allEx().some(x=>x.id===S.selected)?S.selected:allEx()[0]?.id;if(!ex)return[];const [d,id]=ex.split('|');const name=currentPlan()[Number(d)]?.ex.find(x=>x.id===id)?.name;return Array.from({length:Math.max(8,S.week)},(_,i)=>{const week=i+1;const weekPlan=week===1?S.plan:S.plan[0]?.weeklyPlans?.[week];const sameName=weekPlan?.[Number(d)]?.ex.find(x=>x.name===name)?.id;const rows=S.logs.filter(l=>l.week_number===week&&l.day_index===Number(d)&&l.exercise_id===(sameName||id)&&l.completed&&l.weight!==null&&l.reps!==null);return {week:'S'+(i+1),weight:rows.length?Math.max(...rows.map(r=>Number(r.weight))):null,reps:rows.length?Math.max(...rows.map(r=>Number(r.reps))):null,volume:rows.length?rows.reduce((n,r)=>n+Number(r.weight)*Number(r.reps),0):null}})}
function chartUI(){const values=chartData(),pts=values.map((d,i)=>({x:42+i*(310/Math.max(1,values.length-1)),y:d[S.metric]===null?null:Number(d[S.metric])})),existing=pts.filter(p=>p.y!==null);if(!existing.length)return '<div class="empty-chart">Ton graphique apparaîtra après tes premières séries validées.</div>';const max=Math.max(1,...existing.map(x=>x.y))*1.15;const plotted=existing.map(p=>({x:p.x,y:200-p.y/max*160}));return '<svg viewBox="0 0 375 235" role="img" aria-label="Évolution des performances"><line x1="42" y1="200" x2="356" y2="200" stroke="#424e4b"/><line x1="42" y1="120" x2="356" y2="120" stroke="#2c353a" stroke-dasharray="4 6"/><line x1="42" y1="40" x2="356" y2="40" stroke="#2c353a" stroke-dasharray="4 6"/><text x="3" y="45" fill="#71817d" font-size="10">'+Math.round(max)+'</text><text x="8" y="204" fill="#71817d" font-size="10">0</text>'+(plotted.length>1?'<polyline points="'+plotted.map(p=>p.x+','+p.y).join(' ')+'" fill="none" stroke="#c7f26f" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>':'')+plotted.map(p=>'<circle cx="'+p.x+'" cy="'+p.y+'" r="5" fill="#c7f26f"/>').join('')+values.map((d,i)=>(i%Math.ceil(values.length/6)===0?'<text x="'+(42+i*(310/Math.max(1,values.length-1)))+'" y="226" fill="#89949b" text-anchor="middle" font-size="10">'+esc(d.week)+'</text>':'')).join('')+'</svg>'}
function statsUI(){const logs=S.logs.filter(x=>x.completed),volume=logs.reduce((n,l)=>n+(Number(l.weight)||0)*(Number(l.reps)||0),0);const options=allEx();return '<div class="eyebrow">TES PERFORMANCES</div><h1 class="hero-title">Les chiffres<br><em>parlent.</em></h1><div class="statsgrid"><div class="stat"><small>SÉRIES VALIDÉES</small><strong>'+logs.length+'</strong></div><div class="stat"><small>VOLUME TOTAL</small><strong>'+Math.round(volume).toLocaleString('fr-FR')+' <sup>kg</sup></strong></div></div><div class="section-title"><h3>Ta progression</h3></div><label class="field-label">EXERCICE</label><select class="select" id="exercise-select">'+options.map(x=>'<option value="'+esc(x.id)+'" '+((S.selected||options[0]?.id)===x.id?'selected':'')+'>'+esc(x.label)+'</option>').join('')+'</select><div class="seg">'+[['weight','Charge max'],['reps','Répétitions'],['volume','Volume']].map(([v,t])=>'<button data-action="metric" data-metric="'+v+'" class="'+(S.metric===v?'active':'')+'">'+t+'</button>').join('')+'</div><div class="chart">'+chartUI()+'</div><p class="hint">Les graphiques utilisent les séries validées, semaine par semaine. Volume = kg × répétitions.</p><p class="hint">'+(A.session?'Compte connecté : tes données sont synchronisées avec ton compte.':'Mode invité : tes données restent sur ce téléphone. Elles ne sont envoyées à aucun serveur.')+' Utilise le bouton ↓ en haut pour exporter une sauvegarde ; supprimer les données du navigateur peut effacer les données.</p>'}

function importPanelUI(){const preview=S.importPreview;return '<section class="import-panel"><div class="eyebrow">TON ENTRAÎNEMENT, TES CHOIX</div><h2>Importer un programme</h2><p class="hint">Colle une séance ou importe un fichier CSV/TXT. Tu pourras vérifier les exercices avant de les enregistrer. Tout se fait dans ton navigateur.</p><label for="import-text">Programme à importer</label><textarea id="import-text" rows="6" placeholder="Lundi : Pectoraux / Triceps\nDéveloppé couché — 4 x 8 — 70 kg\nDéveloppé incliné — 3 x 10\nMardi : Dos\nTirage vertical — 3 x 12">'+esc(S.importText||'')+'</textarea><label class="import-file-label" for="import-file">Choisir un fichier .csv ou .txt</label><input id="import-file" type="file" accept=".csv,.tsv,.txt,text/plain,text/csv,text/tab-separated-values"><button class="fit-action" data-action="import-preview">Prévisualiser mon import</button><p class="hint">Format CSV : jour;seance;exercice;series;repetitions;repos;charge. Pour un programme sans jour, sélectionne le jour de destination.</p>'+(preview?'<div class="import-preview"><h3>'+preview.count+' exercice(s) reconnu(s)</h3>'+preview.sessions.map((session,i)=>'<div class="import-preview-day"><strong>'+esc(session.day||'Séance unique')+' · '+esc(session.title)+'</strong><p>'+session.ex.map(x=>esc(x.name)+' ('+x.sets+' × '+esc(x.reps)+(x.weight!==null?' · '+x.weight+' kg':'')+')').join(' · ')+'</p></div>').join('')+(preview.multi?'':'<label for="import-day">Jour de destination</label><select id="import-day">'+globalThis.SteroidImport.days.map((d,i)=>'<option value="'+i+'" '+(i===S.importDay?'selected':'')+'>'+d+'</option>').join('')+'</select>')+'<p class="hint">Les séances importées remplaceront les exercices des jours concernés dans le brouillon. Les autres jours resteront inchangés. Aucune modification n’est enregistrée sans confirmation.</p><button class="fit-action" data-action="import-apply">Ajouter au brouillon</button></div>':'')+'</section>'}
function prepareImport(){try{S.importPreview=globalThis.SteroidImport.read(S.importText);render()}catch(e){S.importPreview=null;setNotice('Import : '+e.message,true)}}
function applyImport(){const result=S.importPreview;if(!result)return;const draft=S.draft||structuredClone(S.plan);for(const session of result.sessions){const d=Number.isInteger(session.day)&&session.day>=0?session.day:S.importDay;if(d<0||d>6){setNotice('Jour de séance invalide.',true);return}const existing=draft[d];draft[d]={...existing,title:session.title,focus:'Programme personnel',ex:session.ex.map(x=>({id:uniqueId(),name:x.name,sets:x.sets,reps:x.reps,rest:x.rest,targetWeight:Number.isFinite(x.weight)&&x.weight>=0?x.weight:null}))};}S.draft=draft;S.importPreview=null;S.importText='';render();setNotice('Import ajouté au brouillon. Vérifie les exercices, puis enregistre ton programme.')}

function editUI(){const draft=S.draft||S.plan;return importPanelUI()+'<div class="eyebrow">TON PROGRAMME, TES RÈGLES</div><h1 class="hero-title">Personnalise<br><em>ton plan.</em></h1><p class="hint">Remplace un exercice, modifie les séries ou ajoute un mouvement. Ton historique reste enregistré. Les semaines déjà préparées restent inchangées.</p>'+draft.map((p,d)=>'<section class="edit-day"><h3>'+esc(p.day)+' <span>'+esc(p.title)+'</span></h3>'+p.ex.map((ex,i)=>'<div class="edit-ex" data-sort-day="'+d+'" data-sort-index="'+i+'"><div class="edit-sort-row"><button type="button" class="drag-handle" data-drag-day="'+d+'" data-drag-index="'+i+'" aria-label="Déplacer '+esc(ex.name)+' : maintenir puis glisser" title="Maintenir et glisser pour réordonner">⠿</button><span class="edit-order-label">EXERCICE '+(i+1)+'</span><div class="edit-sort-arrows"><button type="button" data-action="move-exercise" data-day="'+d+'" data-index="'+i+'" data-step="-1" '+(i===0?'disabled':'')+' aria-label="Monter '+esc(ex.name)+'">↑</button><button type="button" data-action="move-exercise" data-day="'+d+'" data-index="'+i+'" data-step="1" '+(i===p.ex.length-1?'disabled':'')+' aria-label="Descendre '+esc(ex.name)+'">↓</button></div></div><input class="edit-name" data-edit="name" data-day="'+d+'" data-index="'+i+'" value="'+esc(ex.name)+'" aria-label="Exercice"><div class="edit-fields"><label>Séries<input type="number" min="1" max="20" data-edit="sets" data-day="'+d+'" data-index="'+i+'" value="'+ex.sets+'"></label><label>Reps<input type="text" data-edit="reps" data-day="'+d+'" data-index="'+i+'" value="'+esc(ex.reps)+'"></label><label>Repos (s)<input type="number" min="0" data-edit="rest" data-day="'+d+'" data-index="'+i+'" value="'+ex.rest+'"></label><button class="delete" data-action="delete" data-day="'+d+'" data-index="'+i+'" title="Supprimer">×</button></div></div>').join('')+(p.ex.length?'<button class="add" data-action="add" data-day="'+d+'">+ Ajouter un exercice</button>':d===3||d===6?'<p class="hint">Jour de récupération</p>':'<button class="add" data-action="add" data-day="'+d+'">+ Ajouter un exercice</button>')+'</section>').join('')+'<button class="primary save" data-action="save-plan">Enregistrer mon programme ✓</button><p class="legal">Les modifications s’appliqueront aux prochaines séances. Les séries enregistrées conservent leurs identifiants.</p>'}
function render(){if(A.view==='welcome'||A.view==='account'||A.view==='onboard'){root.innerHTML='<div class="shell immersive-shell '+(A.view==='welcome'?'is-welcome':A.view==='account'?'is-auth':'is-onboard')+'"><header class="topbar"><div class="brand official-brand"><img src="./steroide-wordmark.svg" alt="STÉROÏDE"></div></header><main>'+(A.view==='welcome'?welcomeUI():A.view==='account'?accountUI():onboardUI())+'</main></div>'+(S.notice?'<div class="toast '+(S.error?'alert':'')+'">'+esc(S.notice)+'</div>':'');return}if(S.loading||!S.plan){root.innerHTML='<div class="boot">STÉROÏDE</div>';return}root.innerHTML='<div class="shell"><header class="topbar"><div class="brand official-brand"><img src="./steroide-wordmark.svg" alt="STÉROÏDE"></div><div class="header-actions"><button class="icon-btn" data-action="account" title="Mon compte" aria-label="Mon compte">◉</button><button class="icon-btn" data-action="backup" title="Exporter une sauvegarde" aria-label="Exporter une sauvegarde">↓</button></div></header><main>'+(S.tab==='today'&&S.workoutScreen==='summary'&&activeWorkout()?.status==='finished'?workoutSummaryUI(activeWorkout()):S.tab==='today'&&activeWorkout()?.mode==='guided'&&activeWorkout()?.status==='active'?guidedWorkoutUI():S.tab==='today'?todayUI():S.tab==='stats'?statsUI():editUI())+'</main><nav class="tabbar">'+buttonNav('today','◫','Séances')+buttonNav('stats','▥','Statistiques')+buttonNav('edit','⚙','Programme')+'</nav></div>'+timerUI()+(S.notice?'<div class="toast '+(S.error?'alert':'')+'">'+esc(S.notice)+'</div>':'')}
function saveSet(ex,s,field,value){if(activeWorkout()?.status==='finished'){setNotice('Séance finalisée : les performances sont verrouillées.',true);return}const prev=logFor(S.day,ex,s);const row={week_number:S.week,day_index:S.day,exercise_id:ex,set_number:s+1,weight:prev?.weight??null,reps:prev?.reps??null,completed:prev?.completed??false,[field]:value};S.logs=[...S.logs.filter(l=>!(l.week_number===S.week&&l.day_index===S.day&&l.exercise_id===ex&&l.set_number===s+1)),row];persist();if(A.session)queueSet(row);if(field==='completed'&&value===true&&!prev?.completed){const item=currentPlan()[S.day]?.ex.find(x=>x.id===ex);if(item)beginRest(item.name,item.rest)}render()}
function moveDraftExercise(day,from,to){const list=S.draft?.[day]?.ex;if(!list||!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>=list.length||to>=list.length||from===to)return false;const [item]=list.splice(from,1);list.splice(to,0,item);return true}
let dragExercise=null;
root.addEventListener('pointerdown',e=>{const handle=e.target.closest('.drag-handle');if(!handle||S.tab!=='edit'||!S.draft)return;if(e.button!==0&&e.pointerType==='mouse')return;const row=handle.closest('.edit-ex');if(!row)return;dragExercise={day:Number(handle.dataset.dragDay),from:Number(handle.dataset.dragIndex),to:Number(handle.dataset.dragIndex),handle,row,pointerId:e.pointerId};handle.setPointerCapture?.(e.pointerId);row.classList.add('is-dragging');e.preventDefault()});
root.addEventListener('pointermove',e=>{const d=dragExercise;if(!d||e.pointerId!==d.pointerId)return;const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('.edit-ex');if(hit&&Number(hit.dataset.sortDay)===d.day){d.to=Number(hit.dataset.sortIndex);root.querySelectorAll('.edit-ex.is-drop-target').forEach(el=>el.classList.remove('is-drop-target'));if(hit!==d.row)hit.classList.add('is-drop-target')}});
function endExerciseDrag(e){const d=dragExercise;if(!d||e.pointerId!==d.pointerId)return;dragExercise=null;d.row.classList.remove('is-dragging');root.querySelectorAll('.edit-ex.is-drop-target').forEach(el=>el.classList.remove('is-drop-target'));if(e.type!=='pointercancel'&&moveDraftExercise(d.day,d.from,d.to))render()}
root.addEventListener('pointerup',endExerciseDrag);
root.addEventListener('pointercancel',endExerciseDrag);
function savePlan(){const draft=S.draft;if(!draft)return;const oldPlan=S.plan;const changed=draft.map((d,i)=>JSON.stringify({title:d.title,focus:d.focus,ex:d.ex})!==JSON.stringify({title:oldPlan[i].title,focus:oldPlan[i].focus,ex:oldPlan[i].ex}));S.plan=structuredClone(draft);const weekly=S.plan?.[0]?.weeklyPlans;if(S.week>1&&weekly?.[S.week]){for(let i=0;i<7;i++){if(!changed[i])continue;const hasLogs=S.logs.some(r=>r.week_number===S.week&&r.day_index===i);if(!hasLogs)weekly[S.week][i]=structuredClone(S.plan[i]);}}persist();if(A.session){cacheAccount();syncProgram().catch(e=>setNotice('Synchronisation impossible : '+e.message,true))};S.tab='today';S.open='auto';setNotice(A.session?'Programme enregistré ✓':'Programme enregistré sur cet appareil ✓')}
const scrollToSectionTop=()=>{if(typeof window.scrollTo==='function')window.scrollTo({top:0,behavior:'instant'});const scroller=document.scrollingElement;if(scroller)scroller.scrollTop=0};
root.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='workout-guided'){startWorkout(true)}else if(a==='workout-classic'){startWorkout(false)}else if(a==='workout-next'||a==='workout-prev'){const p=currentPlan()[S.day],i=p.ex.findIndex(x=>x.id===activeWorkout()?.active_exercise_id),next=p.ex[i+(a==='workout-next'?1:-1)];if(next)selectWorkoutExercise(next.id)}else if(a==='workout-request-finish'){if(activeWorkout()?.status!=='active')return;S.finishPrompt=true;render()}else if(a==='workout-cancel-finish'){S.finishPrompt=false;render()}else if(a==='workout-confirm-finish'){S.finishPrompt=false;S.workoutScreen='summary';finishWorkout()}else if(a==='workout-show-summary'){S.workoutScreen='summary';render()}else if(a==='workout-exit'){S.workoutScreen='';render()}else if(a==='timer-toggle'){if(T.running){T.remaining=timerSeconds();T.running=false;clearInterval(T.interval);T.interval=null}else if(T.remaining>0){T.end=Date.now()+T.remaining*1000;T.running=true;T.interval=setInterval(updateTimer,250)}saveRest();render()}else if(a==='timer-plus'){T.remaining=timerSeconds()+30;if(T.running)T.end=Date.now()+T.remaining*1000;saveRest();render()}else if(a==='timer-close'){T.running=false;T.remaining=0;clearInterval(T.interval);T.interval=null;saveRest();render()}else if(a==='auth-login'){A.mode='login';A.view='account';render()}else if(a==='auth-signup'){A.mode='signup';A.view='account';render()}else if(a==='auth-recover'){A.mode='recover';A.view='account';render()}else if(a==='resend-confirm'){if(!A.email){setNotice('Renseigne ton email pour renvoyer la confirmation.',true);return}try{await req('/auth/v1/resend',{method:'POST',body:{type:'signup',email:A.email,options:{emailRedirectTo:location.origin+location.pathname}}});setNotice('Si ton adresse est en attente de confirmation, un nouvel email a été demandé.')}catch(err){setNotice('Impossible de renvoyer le message : '+err.message,true)}}else if(a==='back-app'){A.view='app';render()}else if(a==='logout'){await flushSets();try{await req('/auth/v1/logout',{method:'POST',token:token()})}catch{}setSession(null);A.profile=null;A.answers=null;S.logs=[];S.plan=seed();S.start=iso(monday(new Date()));S.week=currentWeek(S.start);A.view='welcome';render()}else if(a==='edit-profile'){A.answers=structuredClone(A.profile?.answers||eng().defaults);A.step=0;A.view='onboard';render()}else if(a==='start-account'){A.view='account';A.mode='signup';render()}else if(a==='start-onboard'){A.answers=structuredClone(eng().defaults);A.view='onboard';A.step=0;render();scrollToSectionTop()}else if(a==='keep-plan'){localStorage.setItem('nolsprog-onboarding-seen','1');A.view='app';render()}else if(a==='guest'){A.view='onboard';A.step=0;A.answers=structuredClone(eng().defaults);render()}else if(a==='forgot-password'){const email=prompt('Quelle adresse email est associée à ton compte ?');if(!email)return;try{await req('/auth/v1/recover',{method:'POST',body:{email:email.trim(),redirect_to:location.origin+location.pathname}});setNotice('Si ce compte existe, un email pour définir ton mot de passe va arriver. Regarde aussi les spams.')}catch(e){setNotice('Envoi impossible : '+e.message,true)}}else if(a==='auth-mode'){A.mode=A.mode==='signup'?'login':'signup';render()}else if(a==='account'){A.view='account';A.mode='login';render()}else if(a==='onboard-exit'){A.view=A.session?'app':'welcome';render()}else if(a==='guide-close'){A.guide=false;render();scrollToSectionTop()}else if(a==='guide-edit'){A.guide=false;A.step=Math.max(0,Math.min(onboardingStages.length-1,Number(b.dataset.step)||0));render();scrollToSectionTop()}else if(a==='guide-apply'){
 const d=globalThis.SteroidGuide.diagnostic(A.answers),choice=d.choices[Number(b.dataset.index)];if(!choice)return;
 A.answers=globalThis.SteroidGuide.change(A.answers,choice.patch);
 const next=globalThis.SteroidGuide.diagnostic(A.answers);
 if(next.ok){A.guide=false;A.step=onboardingStages.length-1;render();scrollToSectionTop();setNotice('Ajustement appliqué. Vérifie tes réponses, puis crée ton programme.')}else{A.guide=true;render();scrollToSectionTop()}
 }else if(a==='prev-step'){A.step=Math.max(0,A.step-1);render();scrollToSectionTop()}else if(a==='next-step'){if(A.step<onboardingStages.length-1){A.step++;render();scrollToSectionTop()}else {await finishOnboarding();scrollToSectionTop()}}else if(a==='choice'){A.guide=false;const key=b.dataset.key,v=b.dataset.value;if(key==='days'||key==='priority'){const value=key==='days'?Number(v):v;A.answers[key]=A.answers[key].includes(value)?A.answers[key].filter(x=>x!==value):[...A.answers[key],value]}else A.answers[key]=v;render()}else if(a==='tab'){if(b.dataset.tab==='edit')S.draft=structuredClone(S.plan);S.tab=b.dataset.tab;render();scrollToSectionTop()}else if(a==='day'){S.workoutScreen='';S.finishPrompt=false;S.day=Number(b.dataset.day);S.open='auto';render();scrollToSectionTop()}else if(a==='week'){S.workoutScreen='';S.finishPrompt=false;S.week=Math.max(1,Math.min(52,S.week+Number(b.dataset.step)));try{ensureWeekPlan(S.week)}catch(e){setNotice('Impossible de préparer cette semaine : '+e.message,true)}S.open='auto';render();scrollToSectionTop()}else if(a==='open'){S.open=(S.open===b.dataset.id||(S.open==='auto'&&currentPlan()[S.day].ex[0]?.id===b.dataset.id))?null:b.dataset.id;render()}else if(a==='complete'){const s=Number(b.dataset.set),r=logFor(S.day,b.dataset.ex,s);await saveSet(b.dataset.ex,s,'completed',!r?.completed)}else if(a==='cycle-review'){
 const fatigue=confirm('Bilan du cycle : as-tu ressenti une fatigue importante ou une récupération insuffisante ?');
 const plateau=confirm('As-tu stagné sur plusieurs exercices pendant ce cycle ?');
 setNotice(fatigue?'Réduis temporairement la charge de travail et privilégie la récupération. Aucun changement automatique.':plateau?'Envisage de modifier un ou deux exercices ou leur progression dans Programme.':'Continue ton programme : aucun changement n’est nécessaire si tu progresses et récupères bien.');
 }else if(a==='verify-rir'){
 const ex=currentPlan()[S.day]?.ex.find(x=>x.id===b.dataset.ex);
 if(!ex)return;
 if(!confirm('Toutes les répétitions ont-elles été réalisées avec une technique propre, sans douleur anormale ?'))return;
 const input=prompt('Combien de répétitions supplémentaires aurais-tu pu faire à la fin de ta dernière série ? (RIR : 0 à 5)');
 if(input===null)return;
 const rir=Number(input);
 if(!Number.isInteger(rir)||rir<0||rir>5){setNotice('RIR invalide : saisis un entier entre 0 et 5.',true);return}
 const rows=S.logs.filter(r=>r.week_number===S.week&&r.day_index===S.day&&r.exercise_id===ex.id);
 const result=globalThis.SteroidProgression.evaluate(ex,rows,{technique:true,rir});
 setNotice(result.message,result.status!=='increase');
 }else if(a==='metric'){S.metric=b.dataset.metric;render()}else if(a==='move-exercise'){if(moveDraftExercise(Number(b.dataset.day),Number(b.dataset.index),Number(b.dataset.index)+Number(b.dataset.step)))render()}else if(a==='add'){const d=Number(b.dataset.day);S.draft[d].ex.push(mk('Nouvel exercice',3,'8–12',90));render()}else if(a==='delete'){const d=Number(b.dataset.day),i=Number(b.dataset.index);S.draft[d].ex.splice(i,1);render()}else if(a==='import-preview'){S.importText=root.querySelector('#import-text')?.value||'';prepareImport()}else if(a==='import-apply'){applyImport()}else if(a==='save-plan')await savePlan();else if(a==='backup'){downloadBackup()}});
root.addEventListener('change',async e=>{const el=e.target;if(el.dataset.profile&&A.answers){A.answers[el.dataset.profile]=el.value;return}if(el.id==='import-file'){const file=el.files?.[0];if(!file)return;if(file.size>150000){setNotice('Fichier trop volumineux : maximum 150 Ko.',true);return}try{S.importText=await file.text();S.importPreview=null;render();setNotice('Fichier chargé. Clique sur Prévisualiser mon import.')}catch{setNotice('Impossible de lire ce fichier.',true)}return}if(el.id==='import-day'){S.importDay=Number(el.value);return}if(el.id==='workout-jump'){selectWorkoutExercise(el.value);return}if(el.id==='exercise-select'){S.selected=el.value;render();return}if(el.dataset.field){const v=el.value.trim();if(v&&!Number.isFinite(Number(v)))return;if(v!==''&&(Number(v)<0||Number(v)>(el.dataset.field==='weight'?3000:1000)))return;saveSet(el.dataset.ex,Number(el.dataset.set),el.dataset.field,v===''?null:Number(v));return}if(el.dataset.edit){const d=Number(el.dataset.day),i=Number(el.dataset.index),field=el.dataset.edit;let v=el.value;if(field==='sets')v=Math.max(1,Math.min(20,Number(v)||1));if(field==='rest')v=Math.max(0,Math.min(3600,Number(v)||0));if(field==='name')v=v.slice(0,100).trim()||'Exercice';if(field==='reps')v=v.slice(0,30);S.draft[d].ex[i][field]=v}});
root.addEventListener('submit',async e=>{
 if(e.target.id==='password-form'){e.preventDefault();const password=String(new FormData(e.target).get('password')||'');if(password.length<8)return;try{await req('/auth/v1/user',{method:'PUT',token:token(),body:{password}});A.mode='login';await loadCloud();setNotice('Mot de passe enregistré ✓')}catch(err){setNotice('Impossible de définir le mot de passe : '+err.message,true)}return}
 if(e.target.id!=='auth-form')return;
 e.preventDefault();if(A.busy)return;A.busy=true;
 const data=new FormData(e.target),email=String(data.get('email')||'').trim(),password=String(data.get('password')||'');A.email=email;
 try{
  if(A.mode==='recover'){await req('/auth/v1/recover?redirect_to='+encodeURIComponent(location.origin+location.pathname),{method:'POST',body:{email}});setNotice('Si cette adresse possède un compte, un lien de récupération a été demandé. Vérifie aussi les spams.');return}
  if(password.length<8)throw Error('Le mot de passe doit contenir au moins 8 caractères.');
  const signup=A.mode==='signup';
  const path=signup?'/auth/v1/signup?redirect_to='+encodeURIComponent(location.origin+location.pathname):'/auth/v1/token?grant_type=password';
  const s=await req(path,{method:'POST',body:{email,password}});
  if(!s.access_token){A.mode='verify';A.view='account';render();setNotice('Vérifie ton email pour activer le compte. Tu pourras renvoyer le lien depuis cet écran.');return}
  setSession({...s,expires_at:Math.floor(Date.now()/1000)+(s.expires_in||3600)});
  await loadCloud();setNotice('Compte connecté ✓');
 }catch(err){setNotice('Connexion : '+err.message,true)}
 finally{A.busy=false}
});
loadLocal();initAuth();
